package tech.streamfusion.bench;

import org.apache.flink.table.runtime.functions.SqlFunctionUtils;

/** Supplies the NULL guard normally generated by Flink around its primitive scalar method. */
public final class ReleasedDoubleTruncate {
  private ReleasedDoubleTruncate() {}

  public static Double eval(Double value, Integer scale) {
    return value == null || scale == null ? null : SqlFunctionUtils.struncate(value, scale);
  }
}
